#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "fdtd-2d.h"


/* Array initialization. */
static
void init_array (int tmax,
		 int nx,
		 int ny,
		 DATA_TYPE POLYBENCH_2D(ex,NX,NY,nx,ny),
		 DATA_TYPE POLYBENCH_2D(ey,NX,NY,nx,ny),
		 DATA_TYPE POLYBENCH_2D(hz,NX,NY,nx,ny),
		 DATA_TYPE POLYBENCH_1D(_fict_,TMAX,tmax))
{
  int i, j;

  for (i = 0; i < tmax; i++)
    _fict_[i] = (DATA_TYPE) i;
  for (i = 0; i < nx; i++)
    for (j = 0; j < ny; j++)
      {
	ex[i][j] = ((DATA_TYPE) i*(j+1)) / nx;
	ey[i][j] = ((DATA_TYPE) i*(j+2)) / ny;
	hz[i][j] = ((DATA_TYPE) i*(j+3)) / nx;
      }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int nx,
		 int ny,
		 DATA_TYPE POLYBENCH_2D(ex,NX,NY,nx,ny),
		 DATA_TYPE POLYBENCH_2D(ey,NX,NY,nx,ny),
		 DATA_TYPE POLYBENCH_2D(hz,NX,NY,nx,ny))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("ex");
  for (i = 0; i < nx; i++)
    for (j = 0; j < ny; j++) {
      if ((i * nx + j) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, ex[i][j]);
    }
  POLYBENCH_DUMP_END("ex");
  POLYBENCH_DUMP_FINISH;

  POLYBENCH_DUMP_BEGIN("ey");
  for (i = 0; i < nx; i++)
    for (j = 0; j < ny; j++) {
      if ((i * nx + j) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, ey[i][j]);
    }
  POLYBENCH_DUMP_END("ey");

  POLYBENCH_DUMP_BEGIN("hz");
  for (i = 0; i < nx; i++)
    for (j = 0; j < ny; j++) {
      if ((i * nx + j) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, hz[i][j]);
    }
  POLYBENCH_DUMP_END("hz");
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_fdtd_2d[[gnu::flatten, gnu::noinline]](int tmax,
		    int nx,
		    int ny,
		    DATA_TYPE POLYBENCH_2D(ex,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_2D(ey,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_2D(hz,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_1D(_fict_,TMAX,tmax))
{
  int t, i, j;

#pragma scop

  /* Use PolyBench's possibly reduced problem sizes.  Storing them in
     local constants helps the optimizer reason about loop bounds. */
  const int tmax_ = _PB_TMAX;
  const int nx_   = _PB_NX;
  const int ny_   = _PB_NY;

  /* Create local restrict-qualified aliases.  This makes it explicit
     to the compiler that these arrays do not alias, which improves
     auto-vectorization and scheduling. */
  DATA_TYPE (*restrict ex_)[ny_]  = ex;
  DATA_TYPE (*restrict ey_)[ny_]  = ey;
  DATA_TYPE (*restrict hz_)[ny_]  = hz;
  DATA_TYPE *restrict fict_       = _fict_;

  const DATA_TYPE half         = SCALAR_VAL(0.5);
  const DATA_TYPE seven_tenths = SCALAR_VAL(0.7);

  if (nx_ <= 1)
  {
    /* Degenerate x-dimension: fall back to a direct implementation
       identical to the original kernel.  This keeps the optimized
       schedule below focused on the common case nx_ > 1. */
    for (t = 0; t < tmax_; t++)
    {
      /* ey[0][*] boundary condition. */
      for (j = 0; j < ny_; j++)
        ey_[0][j] = fict_[t];

      /* ey update for i >= 1. (No iterations when nx_ == 1.) */
      for (i = 1; i < nx_; i++)
        for (j = 0; j < ny_; j++)
          ey_[i][j] -= half * (hz_[i][j] - hz_[i-1][j]);

      /* ex update for j >= 1. */
      for (i = 0; i < nx_; i++)
        for (j = 1; j < ny_; j++)
          ex_[i][j] -= half * (hz_[i][j] - hz_[i][j-1]);

      /* hz update on the interior (i < nx_-1, j < ny_-1). */
      for (i = 0; i < nx_ - 1; i++)
        for (j = 0; j < ny_ - 1; j++)
          hz_[i][j] -= seven_tenths *
                       ( (ex_[i][j+1] - ex_[i][j]) +
                         (ey_[i+1][j] - ey_[i][j]) );
    }
  }
  else
  {
    /* Optimized schedule for the common case nx_ > 1.
       We stream over rows in the x-dimension and, for each row i, we:
         - update ey[i+1][*] from old hz[i+1][*] and old hz[i][*],
         - update ex[i][*]   from old hz[i][*],
         - update hz[i][*]   from new ex[i][*] and new ey[i][*]/ey[i+1][*].
       This fuses the three original sweeps (ey, ex, hz) into a
       row-wise pipeline, improving cache reuse while preserving the
       per-element numerical semantics. */

    const int nx_minus1 = nx_ - 1;
    const int nx_minus2 = nx_ - 2;

    for (t = 0; t < tmax_; t++)
    {
      DATA_TYPE fict_t = fict_[t];

      /* 1) Apply boundary condition on ey for the first row. */
      DATA_TYPE *restrict ey_row0 = ey_[0];
#pragma GCC ivdep
      for (j = 0; j < ny_; j++)
        ey_row0[j] = fict_t;

      /* 2) Prologue for i = 0:
            - update ey[1][*] from old hz[1][*] and old hz[0][*],
            - update ex[0][*] from old hz[0][*],
            - update hz[0][*] from new ex[0][*], new ey[0][*], new ey[1][*]. */

      /* ey[1][*] update: uses only old hz values. */
      {
        const int i1 = 1;
        DATA_TYPE *restrict ey_i1 = ey_[i1];
        DATA_TYPE *restrict hz_i1 = hz_[i1];
        DATA_TYPE *restrict hz_i0 = hz_[i1-1]; /* row 0 */

#pragma GCC ivdep
        for (j = 0; j < ny_; j++)
          ey_i1[j] -= half * (hz_i1[j] - hz_i0[j]);
      }

      /* ex[0][*] update: uses only old hz[0][*]. */
      {
        const int i0 = 0;
        DATA_TYPE *restrict ex_i0 = ex_[i0];
        DATA_TYPE *restrict hz_i0 = hz_[i0];

#pragma GCC ivdep
        for (j = 1; j < ny_; j++)
          ex_i0[j] -= half * (hz_i0[j] - hz_i0[j-1]);
      }

      /* hz[0][*] update: uses new ex[0][*], new ey[0][*] and new ey[1][*]. */
      {
        const int i0 = 0;
        DATA_TYPE *restrict hz_i0  = hz_[i0];
        DATA_TYPE *restrict ex_i0  = ex_[i0];
        DATA_TYPE *restrict ey_i0  = ey_[i0];
        DATA_TYPE *restrict ey_ip1 = ey_[i0+1];
        const int ny_minus1 = ny_ - 1;

#pragma GCC ivdep
        for (j = 0; j < ny_minus1; j++)
          hz_i0[j] -= seven_tenths *
                      ( (ex_i0[j+1] - ex_i0[j]) +
                        (ey_ip1[j]   - ey_i0[j]) );
      }

      /* 3) Main streaming loop for 1 <= i <= nx_-2.
            At iteration i:
              - ey[i+1] is computed from old hz[i+1] and old hz[i],
              - ex[i]   is computed from old hz[i],
              - hz[i]   is computed from new ex[i], new ey[i] and ey[i+1]. */
      if (nx_minus2 >= 1)
      {
        const int ny_minus1 = ny_ - 1;

        for (i = 1; i <= nx_minus2; i++)
        {
          /* ey[i+1][*] update: still uses only old hz rows. */
          DATA_TYPE *restrict ey_ip1 = ey_[i+1];
          DATA_TYPE *restrict hz_ip1 = hz_[i+1];
          DATA_TYPE *restrict hz_i   = hz_[i];

#pragma GCC ivdep
          for (j = 0; j < ny_; j++)
            ey_ip1[j] -= half * (hz_ip1[j] - hz_i[j]);

          /* ex[i][*] update: uses old hz[i][*]. */
          DATA_TYPE *restrict ex_i = ex_[i];

#pragma GCC ivdep
          for (j = 1; j < ny_; j++)
            ex_i[j] -= half * (hz_i[j] - hz_i[j-1]);

          /* hz[i][*] update: uses new ex[i][*], new ey[i][*] and ey[i+1][*]. */
          DATA_TYPE *restrict hz_row = hz_i;
          DATA_TYPE *restrict ey_i   = ey_[i];

#pragma GCC ivdep
          for (j = 0; j < ny_minus1; j++)
            hz_row[j] -= seven_tenths *
                         ( (ex_i[j+1] - ex_i[j]) +
                           (ey_ip1[j]  - ey_i[j]) );
        }
      }

      /* 4) Epilogue: update the last ex row (i = nx_-1).
            This row is never used in any hz update, so its position
            relative to hz updates is irrelevant as long as it still
            uses the old hz[nx_-1][*] values, which is the case here
            because hz[nx_-1][*] is never updated. */
      {
        const int ilast = nx_minus1;
        DATA_TYPE *restrict ex_last = ex_[ilast];
        DATA_TYPE *restrict hz_last = hz_[ilast];

#pragma GCC ivdep
        for (j = 1; j < ny_; j++)
          ex_last[j] -= half * (hz_last[j] - hz_last[j-1]);
      }
    } /* end of t loop */
  }

#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int tmax = TMAX;
  int nx = NX;
  int ny = NY;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(ex,DATA_TYPE,NX,NY,nx,ny);
  POLYBENCH_2D_ARRAY_DECL(ey,DATA_TYPE,NX,NY,nx,ny);
  POLYBENCH_2D_ARRAY_DECL(hz,DATA_TYPE,NX,NY,nx,ny);
  POLYBENCH_1D_ARRAY_DECL(_fict_,DATA_TYPE,TMAX,tmax);

  /* Initialize array(s). */
  init_array (tmax, nx, ny,
	      POLYBENCH_ARRAY(ex),
	      POLYBENCH_ARRAY(ey),
	      POLYBENCH_ARRAY(hz),
	      POLYBENCH_ARRAY(_fict_));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_fdtd_2d (tmax, nx, ny,
		  POLYBENCH_ARRAY(ex),
		  POLYBENCH_ARRAY(ey),
		  POLYBENCH_ARRAY(hz),
		  POLYBENCH_ARRAY(_fict_));


  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(nx, ny, POLYBENCH_ARRAY(ex),
				    POLYBENCH_ARRAY(ey),
				    POLYBENCH_ARRAY(hz)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(ex);
  POLYBENCH_FREE_ARRAY(ey);
  POLYBENCH_FREE_ARRAY(hz);
  POLYBENCH_FREE_ARRAY(_fict_);

  return 0;
}
