#include <polybench.h>

/* Include benchmark-specific header. */
#include "fdtd-2d.h"


/* Array initialization. */
static
void init_array (int tmax,
                 int nx,
                 int ny,
                 DATA_TYPE POLYBENCH_2D(ex,NX,NY,nx,ny),
                 DATA_TYPE POLYBENCH_2D(ey,NX,NY,nx,ny),
                 DATA_TYPE POLYBENCH_2D(hz,NX,NY,nx,ny),
                 DATA_TYPE POLYBENCH_1D(_fict_,TMAX,tmax))
{
  int i, j;

  /* Use local restrict-qualified pointers to help the compiler
     optimize initialization and better vectorize the loops. */
  DATA_TYPE (*restrict ex_)[ny]   = (DATA_TYPE (*)[ny])ex;
  DATA_TYPE (*restrict ey_)[ny]   = (DATA_TYPE (*)[ny])ey;
  DATA_TYPE (*restrict hz_)[ny]   = (DATA_TYPE (*)[ny])hz;
  DATA_TYPE *restrict fict_       = (DATA_TYPE *restrict)_fict_;

  for (i = 0; i < tmax; i++)
    fict_[i] = (DATA_TYPE) i;

  for (i = 0; i < nx; i++)
  {
    DATA_TYPE *restrict ex_i = ex_[i];
    DATA_TYPE *restrict ey_i = ey_[i];
    DATA_TYPE *restrict hz_i = hz_[i];

    for (j = 0; j < ny; j++)
    {
      /* Keep the original arithmetic structure to preserve
         floating-point semantics as closely as possible. */
      ex_i[j] = ((DATA_TYPE)i * (j + 1)) / nx;
      ey_i[j] = ((DATA_TYPE)i * (j + 2)) / ny;
      hz_i[j] = ((DATA_TYPE)i * (j + 3)) / nx;
    }
  }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int nx,
                 int ny,
                 DATA_TYPE POLYBENCH_2D(ex,NX,NY,nx,ny),
                 DATA_TYPE POLYBENCH_2D(ey,NX,NY,nx,ny),
                 DATA_TYPE POLYBENCH_2D(hz,NX,NY,nx,ny))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("ex");
  for (i = 0; i < nx; i++)
    for (j = 0; j < ny; j++) {
      if ((i * nx + j) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, ex[i][j]);
    }
  POLYBENCH_DUMP_END("ex");
  POLYBENCH_DUMP_FINISH;

  POLYBENCH_DUMP_BEGIN("ey");
  for (i = 0; i < nx; i++)
    for (j = 0; j < ny; j++) {
      if ((i * nx + j) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, ey[i][j]);
    }
  POLYBENCH_DUMP_END("ey");

  POLYBENCH_DUMP_BEGIN("hz");
  for (i = 0; i < nx; i++)
    for (j = 0; j < ny; j++) {
      if ((i * nx + j) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, hz[i][j]);
    }
  POLYBENCH_DUMP_END("hz");
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_fdtd_2d[[gnu::flatten, gnu::noinline]](int tmax,
                                                   int nx,
                                                   int ny,
                                                   DATA_TYPE POLYBENCH_2D(ex,NX,NY,nx,ny),
                                                   DATA_TYPE POLYBENCH_2D(ey,NX,NY,nx,ny),
                                                   DATA_TYPE POLYBENCH_2D(hz,NX,NY,nx,ny),
                                                   DATA_TYPE POLYBENCH_1D(_fict_,TMAX,tmax))
{
  int t, i, j;

  /* Local restrict-qualified aliases for better optimization.
     These tell the compiler that ex, ey, hz and _fict_ do not alias
     each other, enabling more aggressive vectorization and
     reordering within each loop. */
  DATA_TYPE (*restrict ex_)[ny] = (DATA_TYPE (*)[ny])ex;
  DATA_TYPE (*restrict ey_)[ny] = (DATA_TYPE (*)[ny])ey;
  DATA_TYPE (*restrict hz_)[ny] = (DATA_TYPE (*)[ny])hz;
  DATA_TYPE *restrict fict_     = (DATA_TYPE *restrict)_fict_;

  /* Hoist scalar constants to avoid recomputing SCALAR_VAL()
     inside the innermost loops. */
  const DATA_TYPE c0_5 = SCALAR_VAL(0.5);
  const DATA_TYPE c0_7 = SCALAR_VAL(0.7);

#pragma scop

  for (t = 0; t < _PB_TMAX; t++)
  {
    /* Time-dependent boundary condition on ey[0][:]. */
    {
      DATA_TYPE *restrict ey0 = ey_[0];
      const DATA_TYPE fict_t  = fict_[t];

      /* Independent updates over j: safe to vectorize. */
#pragma GCC ivdep
      for (j = 0; j < _PB_NY; j++)
        ey0[j] = fict_t;
    }

    /* Update ey using differences of hz in the i-direction. */
    for (i = 1; i < _PB_NX; i++)
    {
      DATA_TYPE *restrict ey_i    = ey_[i];
      DATA_TYPE *restrict hz_i    = hz_[i];
      DATA_TYPE *restrict hz_im1  = hz_[i - 1];

      /* Each iteration only touches ey_i[j] and reads hz_i / hz_im1,
         so there are no loop-carried dependencies in j. */
#pragma GCC ivdep
      for (j = 0; j < _PB_NY; j++)
        ey_i[j] = ey_i[j] - c0_5 * (hz_i[j] - hz_im1[j]);
    }

    /* Update ex using differences of hz in the j-direction. */
    for (i = 0; i < _PB_NX; i++)
    {
      DATA_TYPE *restrict ex_i = ex_[i];
      DATA_TYPE *restrict hz_i = hz_[i];

      /* Each j-update is independent; hz is read-only here. */
#pragma GCC ivdep
      for (j = 1; j < _PB_NY; j++)
        ex_i[j] = ex_i[j] - c0_5 * (hz_i[j] - hz_i[j - 1]);
    }

    /* Update hz using spatial derivatives of ex and ey. */
    for (i = 0; i < _PB_NX - 1; i++)
    {
      DATA_TYPE *restrict hz_i   = hz_[i];
      DATA_TYPE *restrict ex_i   = ex_[i];
      DATA_TYPE *restrict ey_i   = ey_[i];
      DATA_TYPE *restrict ey_ip1 = ey_[i + 1];

      /* Reads from ex/ey and writes to distinct hz_i[j];
         again, no loop-carried dependencies in j. */
#pragma GCC ivdep
      for (j = 0; j < _PB_NY - 1; j++)
        hz_i[j] = hz_i[j]
                  - c0_7 * ((ex_i[j + 1] - ex_i[j]) +
                            (ey_ip1[j]   - ey_i[j]));
    }
  }

#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int tmax = TMAX;
  int nx = NX;
  int ny = NY;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(ex,DATA_TYPE,NX,NY,nx,ny);
  POLYBENCH_2D_ARRAY_DECL(ey,DATA_TYPE,NX,NY,nx,ny);
  POLYBENCH_2D_ARRAY_DECL(hz,DATA_TYPE,NX,NY,nx,ny);
  POLYBENCH_1D_ARRAY_DECL(_fict_,DATA_TYPE,TMAX,tmax);

  /* Initialize array(s). */
  init_array (tmax, nx, ny,
              POLYBENCH_ARRAY(ex),
              POLYBENCH_ARRAY(ey),
              POLYBENCH_ARRAY(hz),
              POLYBENCH_ARRAY(_fict_));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_fdtd_2d (tmax, nx, ny,
                  POLYBENCH_ARRAY(ex),
                  POLYBENCH_ARRAY(ey),
                  POLYBENCH_ARRAY(hz),
                  POLYBENCH_ARRAY(_fict_));


  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(nx, ny, POLYBENCH_ARRAY(ex),
                                    POLYBENCH_ARRAY(ey),
                                    POLYBENCH_ARRAY(hz)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(ex);
  POLYBENCH_FREE_ARRAY(ey);
  POLYBENCH_FREE_ARRAY(hz);
  POLYBENCH_FREE_ARRAY(_fict_);

  return 0;
}
