#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "fdtd-2d.h"


/* Array initialization. */
static
void init_array (int tmax,
		 int nx,
		 int ny,
		 DATA_TYPE POLYBENCH_2D(ex,NX,NY,nx,ny),
		 DATA_TYPE POLYBENCH_2D(ey,NX,NY,nx,ny),
		 DATA_TYPE POLYBENCH_2D(hz,NX,NY,nx,ny),
		 DATA_TYPE POLYBENCH_1D(_fict_,TMAX,tmax))
{
  int i, j;

  /* Initialize fictitious boundary array. */
  for (i = 0; i < tmax; i++)
    _fict_[i] = (DATA_TYPE) i;

  /* Precompute reciprocals to avoid repeated divisions. */
  const DATA_TYPE inv_nx = SCALAR_VAL(1.0) / (DATA_TYPE)nx;
  const DATA_TYPE inv_ny = SCALAR_VAL(1.0) / (DATA_TYPE)ny;

  /* Initialize field arrays with improved locality and fewer divisions. */
  for (i = 0; i < nx; i++)
  {
    DATA_TYPE di = (DATA_TYPE)i;
    DATA_TYPE *ex_i = ex[i];
    DATA_TYPE *ey_i = ey[i];
    DATA_TYPE *hz_i = hz[i];

    for (j = 0; j < ny; j++)
    {
      DATA_TYPE dj = (DATA_TYPE)j;

      ex_i[j] = di * (dj + SCALAR_VAL(1.0)) * inv_nx;
      ey_i[j] = di * (dj + SCALAR_VAL(2.0)) * inv_ny;
      hz_i[j] = di * (dj + SCALAR_VAL(3.0)) * inv_nx;
    }
  }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int nx,
		 int ny,
		 DATA_TYPE POLYBENCH_2D(ex,NX,NY,nx,ny),
		 DATA_TYPE POLYBENCH_2D(ey,NX,NY,nx,ny),
		 DATA_TYPE POLYBENCH_2D(hz,NX,NY,nx,ny))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("ex");
  for (i = 0; i < nx; i++)
