/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_fdtd_2d[[gnu::flatten, gnu::noinline]](int tmax,
		    int nx,
		    int ny,
		    DATA_TYPE POLYBENCH_2D(ex,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_2D(ey,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_2D(hz,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_1D(_fict_,TMAX,tmax))
{
  int t, i, j;

#pragma scop

  /* Use PolyBench loop bounds (compile-time constants) for optimization. */
  const int NX_   = _PB_NX;
  const int NY_   = _PB_NY;
  const int TMAX_ = _PB_TMAX;

  /* Create restrict-qualified views to help the compiler with
     vectorization and alias analysis. The underlying storage is
     the same as the PolyBench arrays. */
  DATA_TYPE (* restrict ex_)[NY_] = (DATA_TYPE (*)[NY_])ex;
  DATA_TYPE (* restrict ey_)[NY_] = (DATA_TYPE (*)[NY_])ey;
  DATA_TYPE (* restrict hz_)[NY_] = (DATA_TYPE (*)[NY_])hz;
  DATA_TYPE * restrict fict_      = _fict_;

  const DATA_TYPE half  = SCALAR_VAL(0.5);
  const DATA_TYPE alpha = SCALAR_VAL(0.7);

  /* Time-stepping loop. */
  for (t = 0; t < TMAX_; t++)
  {
    const DATA_TYPE fict_t = fict_[t];

    /* Boundary condition: ey[0][j] = _fict_[t] for all j. */
    {
      DATA_TYPE * restrict ey0 = ey_[0];

      #pragma GCC ivdep
      for (j = 0; j < NY_; j++)
        ey0[j] = fict_t;
    }

    /* Fused row-wise update of:
       - ey rows 1..NX_-1,
       - ex rows 0..NX_-2,
       - hz rows 0..NX_-2.

       This reorders the original three sweeps into a single
       pipeline over rows, substantially improving data locality:

       Original order per time step:
         1) ey: all rows (using old hz)
         2) ex: all rows (using old hz)
         3) hz: all interior rows (using new ex, new ey)

       New order:
         for i = 0 .. NX_-2
           a) update ey[i+1][:]   using old hz[i][:],   old hz[i+1][:]
           b) update ex[i][:]     using old hz[i][:]
           c) update hz[i][:]     using new ex[i][:],
                                   new ey[i][:], new ey[i+1][:]

       The dependencies are preserved:
       - ey[i+1] still uses only old hz rows.
       - ex[i]   still uses only old hz row i.
       - hz[i]   uses the newly updated ex[i], ey[i], ey[i+1].

       Each hz row is not updated until it has been used in all
       required ey/ex updates, so the numerical result matches
       the original scalar semantics (up to standard FP reorderings). */
    for (i = 0; i < NX_ - 1; i++)
    {
      DATA_TYPE * restrict ey_i   = ey_[i];     /* ey[i][:]   */
      DATA_TYPE * restrict ey_ip1 = ey_[i + 1]; /* ey[i+1][:] */
      DATA_TYPE * restrict ex_i   = ex_[i];     /* ex[i][:]   */
      DATA_TYPE * restrict hz_i   = hz_[i];     /* hz[i][:]   */
      DATA_TYPE * restrict hz_ip1 = hz_[i + 1]; /* hz[i+1][:] */

      /* ey[i+1][j] = ey[i+1][j] - 0.5 * (hz[i+1][j] - hz[i][j]) */
      #pragma GCC ivdep
      for (j = 0; j < NY_; j++)
      {
        ey_ip1[j] -= half * (hz_ip1[j] - hz_i[j]);
      }

      /* ex[i][j] = ex[i][j] - 0.5 * (hz[i][j] - hz[i][j-1]),
         for j >= 1; ex[i][0] remains unchanged. */
      #pragma GCC ivdep
      for (j = 1; j < NY_; j++)
      {
        ex_i[j] -= half * (hz_i[j] - hz_i[j - 1]);
      }

      /* hz[i][j] = hz[i][j] - 0.7 * (ex[i][j+1] - ex[i][j]
                                      + ey[i+1][j] - ey[i][j]),
         for j in [0, NY_-2]. Uses newly updated ex and ey rows. */
      #pragma GCC ivdep
      for (j = 0; j < NY_ - 1; j++)
      {
        hz_i[j] -= alpha *
                   ( (ex_i[j + 1] - ex_i[j]) +
                     (ey_ip1[j]   - ey_i[j]) );
      }
    }

    /* Last ex row (i = NX_-1) update.
       This row is not used in the hz update (hz only goes up to NX_-2),
       so it can be updated after the fused loop without affecting
       dependencies. This matches the original ex-update coverage. */
    {
      const int i_last = NX_ - 1;
      DATA_TYPE * restrict ex_last = ex_[i_last];
      DATA_TYPE * restrict hz_last = hz_[i_last];

      #pragma GCC ivdep
      for (j = 1; j < NY_; j++)
      {
        ex_last[j] -= half * (hz_last[j] - hz_last[j - 1]);
      }
    }
  }

#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int tmax = TMAX;
  int nx = NX;
  int ny = NY;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(ex,DATA_TYPE,NX,NY,nx,ny);
  POLYBENCH_2D_ARRAY_DECL(ey,DATA_TYPE,NX,NY,nx,ny);
  POLYBENCH_2D_ARRAY_DECL(hz,DATA_TYPE,NX,NY,nx,ny);
  POLYBENCH_1D_ARRAY_DECL(_fict_,DATA_TYPE,TMAX,tmax);

  /* Initialize array(s). */
  init_array (tmax, nx, ny,
	      POLYBENCH_ARRAY(ex),
	      POLYBENCH_ARRAY(ey),
	      POLYBENCH_ARRAY(hz),
	      POLYBENCH_ARRAY(_fict_));

