  (int tmax,
   int nx,
   int ny,
   DATA_TYPE POLYBENCH_2D(ex,NX,NY,nx,ny),
   DATA_TYPE POLYBENCH_2D(ey,NX,NY,nx,ny),
   DATA_TYPE POLYBENCH_2D(hz,NX,NY,nx,ny),
   DATA_TYPE POLYBENCH_1D(_fict_,TMAX,tmax))
{
  int t, i, j;

#pragma scop

  /* Cache the (possibly transformed) problem sizes used by PolyBench. */
  const int tmax_ = _PB_TMAX;
  const int nx_   = _PB_NX;
  const int ny_   = _PB_NY;

  /* Local, restrict-qualified, 1D views of the 2D arrays.
     This tells the compiler that ex, ey and hz do not alias and that each
     is laid out contiguously in row-major order, which helps vectorization
     and improves generated address arithmetic. */
  DATA_TYPE *restrict ex_data   = &ex[0][0];
  DATA_TYPE *restrict ey_data   = &ey[0][0];
  DATA_TYPE *restrict hz_data   = &hz[0][0];
  DATA_TYPE *restrict fict_data = &_fict_[0];

  /* Hoist scalar constants out of the loops to avoid repeated conversions
     of the SCALAR_VAL macro. */
  const DATA_TYPE c_half = SCALAR_VAL(0.5);
  const DATA_TYPE c_07   = SCALAR_VAL(0.7);

  for (t = 0; t < tmax_; t++)
    {
      const DATA_TYPE ft = fict_data[t];

      /* ey[0][j] = _fict_[t]  (boundary condition on the first row).  */
      {
        DATA_TYPE *restrict ey_row0 = ey_data; /* row i = 0 */

        /* Inner loop walks contiguous memory (j is the fastest-varying
           dimension).  The ivdep/unroll pragmas explicitly state that the
           iterations are independent and can be vectorized and unrolled. */
#pragma GCC ivdep
#pragma GCC unroll 8
        for (j = 0; j < ny_; j++)
          ey_row0[j] = ft;
      }

      /* Update ey for rows i = 1..nx_-1:
         ey[i][j] -= 0.5 * (hz[i][j] - hz[i-1][j]); */
      for (i = 1; i < nx_; i++)
        {
          const int offset_i  = i * ny_;
          const int offset_im1 = offset_i - ny_;

          DATA_TYPE       *restrict ey_row  = ey_data + offset_i;
          const DATA_TYPE *restrict hz_row  = hz_data + offset_i;
          const DATA_TYPE *restrict hz_im1  = hz_data + offset_im1;

#pragma GCC ivdep
#pragma GCC unroll 8
          for (j = 0; j < ny_; j++)
            ey_row[j] -= c_half * (hz_row[j] - hz_im1[j]);
        }

      /* Update ex for columns j = 1..ny_-1:
         ex[i][j] -= 0.5 * (hz[i][j] - hz[i][j-1]); */
      for (i = 0; i < nx_; i++)
        {
          const int offset_i = i * ny_;

          DATA_TYPE       *restrict ex_row = ex_data + offset_i;
          const DATA_TYPE *restrict hz_row = hz_data + offset_i;

          /* j = 0 is a boundary value and remains unchanged,
             so we start from j = 1 as in the original code. */
#pragma GCC ivdep
#pragma GCC unroll 8
          for (j = 1; j < ny_; j++)
            ex_row[j] -= c_half * (hz_row[j] - hz_row[j-1]);
        }

      /* Update hz over interior points:
         hz[i][j] -= 0.7 * (ex[i][j+1] - ex[i][j] +
                            ey[i+1][j] - ey[i][j]); */
      for (i = 0; i < nx_ - 1; i++)
        {
          const int offset_i   = i * ny_;
          const int offset_ip1 = offset_i + ny_;

          DATA_TYPE       *restrict hz_row  = hz_data + offset_i;
          const DATA_TYPE *restrict ex_row  = ex_data + offset_i;
          const DATA_TYPE *restrict ey_row  = ey_data + offset_i;
          const DATA_TYPE *restrict ey_ip1  = ey_data + offset_ip1;

#pragma GCC ivdep
#pragma GCC unroll 8
          for (j = 0; j < ny_ - 1; j++)
            hz_row[j] -= c_07 * ((ex_row[j+1] - ex_row[j]) +
                                 (ey_ip1[j]   - ey_row[j]));
        }
    }

#pragma endscop
}


